    colors = set(v for row in grid for v in row) - {background}
    for color in colors:
        prefix = [[0] * (w + 1) for _ in range(h + 1)]
        for r in range(h):
            run = 0
            for c in range(w):
                run += grid[r][c] == color
                prefix[r + 1][c + 1] = prefix[r][c + 1] + run
        for r0 in range(h):
            for r1 in range(r0 + 1, h):
                height = r1 - r0 + 1
                for c0 in range(w):
                    for c1 in range(c0 + 1, w):
                        width = c1 - c0 + 1
                        area = height * width
                        if area < 4:
                            continue
                        count = (prefix[r1 + 1][c1 + 1] - prefix[r0][c1 + 1]
